const CORE_SYMBOLS=["KAS","IGRA","KSKD","IKAS","ZAP"];
function tr(k){return T[lang]?.[k]||T.en[k]||k}function l(obj){return typeof obj==="object"?(obj[lang]||obj.en||""):obj}function usd(n){return Number(n||0).toLocaleString("en-US",{style:"currency",currency:"USD",maximumFractionDigits:n<1?4:2})}function num(n){return Number(n||0).toLocaleString("en-US")}function toggleMenu(){document.getElementById("navlinks").classList.toggle("open")}
function setLanguage(v){lang=v;localStorage.setItem("kaspaRadarLang",lang);applyLanguage();renderAll();document.documentElement.lang=lang}function applyLanguage(){const s=document.getElementById("languageSelect");if(s)s.value=lang;document.querySelectorAll("[data-i18n]").forEach(el=>el.textContent=tr(el.dataset.i18n));document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>el.placeholder=tr(el.dataset.i18nPlaceholder))}
function getWatchlist(){return JSON.parse(localStorage.getItem(watchKey)||"[]")}function setWatchlist(v){localStorage.setItem(watchKey,JSON.stringify(v));renderWatchlist();renderProjects();renderCoreProjects()}
function keiScore(p){return Math.round((p.development||0)*weights.development+(p.adoption||0)*weights.adoption+(p.liquidity||0)*weights.liquidity+(p.community||0)*weights.community+(p.fundamentals||0)*weights.fundamentals)}function opportunityScore(p){return Math.round((keiScore(p)*.45)+((p.momentumRaw||0)*.35)+((100-(p.riskRaw||0))*.20))}
async function loadData(){try{const res=await fetch("data/projects.json");if(res.ok)projects=await res.json();else projects=structuredClone(DEFAULT_PROJECTS)}catch(e){projects=structuredClone(DEFAULT_PROJECTS)}try{const nr=await fetch("data/news.json");if(nr.ok)news=await nr.json();else news=structuredClone(DEFAULT_NEWS)}catch(e){news=structuredClone(DEFAULT_NEWS)}applyLanguage();renderAll();}
function renderAll(){renderCoreProjects();renderEcosystemHealth();renderTrending();renderNewProjects();renderProjects();renderNews();renderWatchlist();renderPortfolioInputs();updateMarketScore();calculateMining();setupAdmin()}
function updateMarketScore(){if(!projects.length)return;document.getElementById("marketScore").innerText=Math.round(projects.reduce((a,p)=>a+keiScore(p),0)/projects.length);let top=[...projects].sort((a,b)=>opportunityScore(b)-opportunityScore(a))[0];let risk=[...projects].sort((a,b)=>(b.riskRaw||0)-(a.riskRaw||0))[0];document.getElementById("topOpportunity").innerText=top.symbol+" "+opportunityScore(top);document.getElementById("highestRisk").innerText=risk.symbol+" "+risk.riskRaw}
function renderCoreProjects(){const el=document.getElementById("coreGrid");if(!el)return;const core=CORE_SYMBOLS.map(s=>projects.find(p=>(p.symbol||"").toUpperCase()===s)).filter(Boolean);el.innerHTML=core.map(p=>`<div class="core-card"><div class="coin-logo">${(p.logoText||p.symbol).slice(0,4)}</div><div class="symbol">${p.symbol}</div><h3>${p.name}</h3><div class="core-price">${p.price?usd(p.price):"—"}</div><div class="core-meta"><span>MC: ${p.marketCap?usd(p.marketCap):"—"}</span><span>Vol: ${p.volume24h?usd(p.volume24h):"—"}</span><span>KEI: ${keiScore(p)}/100</span><span>${tr("opportunity")}: ${opportunityScore(p)}/100</span></div><div class="card-actions"><button class="btn secondary smallbtn" onclick="openProject('${p.id}')">${tr("details")}</button><button class="btn primary smallbtn" onclick="toggleWatch('${p.id}')">${tr("watchlistAdd")}</button></div></div>`).join("")}
function ecosystemHealth(){const core=projects.filter(p=>CORE_SYMBOLS.includes((p.symbol||"").toUpperCase()));const use=core.length?core:projects;return use.length?Math.round(use.reduce((a,p)=>a+keiScore(p),0)/use.length):0}function renderEcosystemHealth(){const el=document.getElementById("ecosystemHealthScore");if(el)el.textContent=ecosystemHealth()}
function renderTrending(){const el=document.getElementById("trendingGrid");if(!el)return;const top=[...projects].sort((a,b)=>opportunityScore(b)-opportunityScore(a)).slice(0,3);el.innerHTML=top.map((p,i)=>`<div class="trend-card"><div class="trend-rank">#${i+1}</div><div class="symbol">${p.symbol}</div><h3>${p.name}</h3><p class="muted">${l(p.category)}</p><div class="trend-score">${opportunityScore(p)}/100</div><p class="muted">${tr("momentum")}: ${p.momentumRaw}/100 · ${tr("risk")}: ${p.riskRaw}/100</p><button class="btn secondary smallbtn" onclick="openProject('${p.id}')">${tr("details")}</button></div>`).join("")}
function renderNewProjects(){const el=document.getElementById("newProjectsBox");if(!el)return;const newest=[...projects].sort((a,b)=>String(b.addedAt||"").localeCompare(String(a.addedAt||""))).slice(0,5);el.innerHTML=newest.map(p=>`<div class="new-item"><div><strong>${p.symbol}</strong> <span class="muted">${p.name} · ${l(p.category)}</span></div><button class="btn secondary smallbtn" onclick="openProject('${p.id}')">${tr("details")}</button></div>`).join("")}
function renderProjects(){const q=(document.getElementById("searchInput")?.value||"").toLowerCase();const risk=document.getElementById("riskFilter")?.value||"all";const sort=document.getElementById("sortMode")?.value||"kei";const wl=getWatchlist();const grid=document.getElementById("projectGrid");if(!grid)return;grid.innerHTML="";let arr=projects.filter(p=>risk==="all"||p.risk?.en===risk).filter(p=>[p.name,p.symbol,l(p.category),l(p.description),...(p.tags||[])].join(" ").toLowerCase().includes(q));if(sort==="kei")arr.sort((a,b)=>keiScore(b)-keiScore(a));if(sort==="opportunity")arr.sort((a,b)=>opportunityScore(b)-opportunityScore(a));if(sort==="momentum")arr.sort((a,b)=>(b.momentumRaw||0)-(a.momentumRaw||0));if(sort==="risk")arr.sort((a,b)=>(b.riskRaw||0)-(a.riskRaw||0));if(sort==="marketCap")arr.sort((a,b)=>(b.marketCap||0)-(a.marketCap||0));arr.forEach(p=>{const saved=wl.includes(p.id);const div=document.createElement("div");div.className="project-card";div.innerHTML=`<div class="card-top"><div><div class="symbol">${p.symbol}</div><h3>${p.name}</h3><div class="price">${usd(p.price)} · MC ${usd(p.marketCap)}</div><p class="desc">${l(p.description)}</p></div><div class="score">${keiScore(p)}</div></div><div class="metrics"><div class="metric"><strong>${opportunityScore(p)}/100</strong><span>${tr("opportunity")}</span></div><div class="metric"><strong>${l(p.risk)}</strong><span>${tr("risk")}</span></div><div class="metric"><strong>${l(p.momentum)}</strong><span>${tr("momentum")}</span></div><div class="metric"><strong>${usd(p.volume24h)}</strong><span>${tr("volume")}</span></div></div><div class="tags">${(p.tags||[]).map(t=>`<span class="tag">${t}</span>`).join("")}</div><div class="card-actions"><button class="btn secondary smallbtn" onclick="openProject('${p.id}')">${tr("details")}</button><button class="btn ${saved?"primary":"secondary"} smallbtn" onclick="toggleWatch('${p.id}')">${saved?tr("saved"):tr("watchlistAdd")}</button></div>`;grid.appendChild(div)})}
function toggleWatch(id){let wl=getWatchlist();wl=wl.includes(id)?wl.filter(x=>x!==id):[...wl,id];setWatchlist(wl)}function resetWatchlist(){setWatchlist([])}function renderWatchlist(){const box=document.getElementById("watchlistBox");if(!box)return;const wl=getWatchlist();if(!wl.length){box.innerHTML=`<p class="muted">${tr("noWatch")}</p>`;return}box.innerHTML=wl.map(id=>{const p=projects.find(x=>x.id===id);return p?`<div class="watch-item"><div><strong>${p.symbol}</strong> <span class="muted">${l(p.watchReason)} · ${usd(p.price)}</span></div><button class="btn secondary smallbtn" onclick="toggleWatch('${p.id}')">${tr("remove")}</button></div>`:""}).join("")}
function exportWatchlist(){downloadJson(getWatchlist().map(id=>projects.find(p=>p.id===id)).filter(Boolean),"kaspa-radar-watchlist.json")}function exportProjects(){downloadJson(projects,"kaspa-radar-projects.json")}function downloadJson(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function openProject(id){const p=projects.find(x=>x.id===id);if(!p)return;const modal=document.getElementById("modal");const card=document.getElementById("modalCard");card.innerHTML=`<button class="btn secondary smallbtn" onclick="document.getElementById('modal').classList.add('hidden')">${tr("close")}</button><p class="eyebrow">${l(p.category)}</p><h2>${p.name} (${p.symbol})</h2><p class="desc">${l(p.thesis)}</p><div class="metrics"><div class="metric"><strong>${usd(p.price)}</strong><span>${tr("price")}</span></div><div class="metric"><strong>${usd(p.marketCap)}</strong><span>${tr("marketCap")}</span></div><div class="metric"><strong>${keiScore(p)}/100</strong><span>KEI Score</span></div><div class="metric"><strong>${opportunityScore(p)}/100</strong><span>${tr("opportunity")}</span></div></div>${metricBar(tr("development"),p.development)}${metricBar(tr("adoption"),p.adoption)}${metricBar(tr("liquidity"),p.liquidity)}${metricBar(tr("community"),p.community)}${metricBar(tr("fundamentals"),p.fundamentals)}<div class="metrics"><div class="metric"><strong>${p.riskRaw}/100</strong><span>${tr("riskScore")}</span></div><div class="metric"><strong>${p.momentumRaw}/100</strong><span>${tr("momentumScore")}</span></div></div>`;modal.classList.remove("hidden")}function metricBar(n,v){return `<label>${n} ${v}/100</label><div class="bar"><span style="width:${v}%"></span></div>`}function closeModal(e){if(e.target.id==="modal")e.currentTarget.classList.add("hidden")}
function renderNews(){const el=document.getElementById("newsGrid");if(!el)return;el.innerHTML=news.map(n=>`<div class="news-card"><p class="eyebrow">${n.date} · ${n.project}</p><h3>${l(n.title)}</h3><p class="muted">${tr("source")}: ${n.source}</p><span class="impact">${tr("impact")}: ${l(n.impact)}</span></div>`).join("")}
function renderPortfolioInputs(){const box=document.getElementById("portfolioInputs");if(!box)return;box.innerHTML=projects.map(p=>`<label>${p.name} (${p.symbol}) ${tr("amount")}</label><input id="pf_${p.id}" type="number" value="${document.getElementById("pf_"+p.id)?.value||0}" step="0.01" oninput="calculatePortfolio()">`).join("")+`<button class="btn primary full" onclick="calculatePortfolio()">${tr("calcPortfolio")}</button>`;calculatePortfolio()}
function calculatePortfolio(){let total=0;let rows=[];projects.forEach(p=>{const amount=Number(document.getElementById("pf_"+p.id)?.value||0);const value=amount*(p.price||0);total+=value;if(amount>0)rows.push(`<div class="result-item"><small>${p.symbol} · ${num(amount)} tokens</small><strong>${usd(value)}</strong></div>`)});const el=document.getElementById("portfolioResult");if(el)el.innerHTML=`<h3>${tr("portfolioVal")}</h3><div class="big-score">${usd(total)}</div><div class="result-grid">${rows.length?rows.join(""):`<p class="muted">${tr("enterAmounts")}</p>`}</div>`}
function calculateMining(){const model=(document.getElementById("minerModel")?.value||"400|100").split("|");const watt=Number(model[1]);const kasDay=Number(document.getElementById("kasPerDay")?.value||0);const price=Number(document.getElementById("kasPrice")?.value||0);const power=Number(document.getElementById("powerPrice")?.value||0);const hw=Number(document.getElementById("hardwareCost")?.value||0);const rev=kasDay*price;const elec=(watt/1000)*24*power;const profit=rev-elec;const month=profit*30;const year=profit*365;const roi=profit>0?Math.ceil(hw/profit):tr("never");const el=document.getElementById("miningResult");if(el)el.innerHTML=`<h3>${tr("result")}</h3><div class="result-grid"><div class="result-item"><small>${tr("revenueDay")}</small><strong>${usd(rev)}</strong></div><div class="result-item"><small>${tr("electricityDay")}</small><strong>${usd(elec)}</strong></div><div class="result-item"><small>${tr("netProfitDay")}</small><strong>${usd(profit)}</strong></div><div class="result-item"><small>${tr("netProfitMonth")}</small><strong>${usd(month)}</strong></div><div class="result-item"><small>${tr("netProfitYear")}</small><strong>${usd(year)}</strong></div><div class="result-item"><small>${tr("breakEven")}</small><strong>${roi} ${profit>0?tr("days"):""}</strong></div></div>`}
