function saveAdminProject(){const p=projects.find(x=>x.id===adminProject.value);if(!p)return;p.price=Number(adminPrice.value||0);p.marketCap=Number(adminMarketCap.value||0);p.volume24h=Number(adminVolume.value||0);p.development=Number(adminDevelopment.value||0);p.adoption=Number(adminAdoption.value||0);p.liquidity=Number(adminLiquidity.value||0);p.community=Number(adminCommunity.value||0);p.fundamentals=Number(adminFundamentals.value||0);p.riskRaw=Number(adminRiskRaw.value||0);p.momentumRaw=Number(adminMomentumRaw.value||0);p.api={provider:adminApiId.value?"coingecko":"manual",id:adminApiId.value||""};p.github=(adminGithubRepos.value||"").split(",").map(x=>x.trim()).filter(Boolean).map(x=>{const [owner,repo]=x.split("/");return {owner,repo}}).filter(x=>x.owner&&x.repo);p.defillama={slug:adminDefillamaSlug.value||""};renderAll()}function renderAdminPreview(p){const el=document.getElementById("adminPreview");if(el)el.innerHTML=`<div class="result-grid"><div class="result-item"><small>KEI</small><strong>${keiScore(p)}/100</strong></div><div class="result-item"><small>${tr("opportunity")}</small><strong>${opportunityScore(p)}/100</strong></div><div class="result-item"><small>${tr("price")}</small><strong>${usd(p.price)}</strong></div><div class="result-item"><small>${tr("marketCap")}</small><strong>${usd(p.marketCap)}</strong></div></div>`}
