/* v1.7 Support functions */
async function copySupportAddress(elementId, button){
  const el = document.getElementById(elementId);
  if(!el) return;
  const text = el.textContent.trim();
  try{
    await navigator.clipboard.writeText(text);
    const old = button.textContent;
    button.textContent = tr("copied");
    setTimeout(()=>button.textContent = old, 1400);
  }catch(e){
    const range = document.createRange();
    range.selectNodeContents(el);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
    const old = button.textContent;
    button.textContent = tr("selectCopy");
    setTimeout(()=>button.textContent = old, 1800);
  }
}
function toggleQR(id){
  const el = document.getElementById(id);
  if(el) el.classList.toggle("hidden");
}


/* v3 KAS Live Data - CoinGecko, frontend only */
async function fetchKasLiveData(){
  const status = document.getElementById("apiStatus");
  if(status) status.textContent = lang === "de" ? "Lade KAS Live-Daten..." : "Loading KAS live data...";

  try{
    const url = "https://api.coingecko.com/api/v3/simple/price?ids=kaspa&vs_currencies=usd&include_market_cap=true&include_24hr_vol=true&include_24hr_change=true&include_last_updated_at=true";
    const res = await fetch(url, { headers: { "accept": "application/json" } });
    if(!res.ok) throw new Error("CoinGecko API error " + res.status);

    const data = await res.json();
    const kas = data.kaspa;
    if(!kas) throw new Error("No KAS data returned");

    const p = projects.find(x => (x.symbol || "").toUpperCase() === "KAS");
    if(p){
      p.price = kas.usd ?? p.price;
      p.marketCap = kas.usd_market_cap ?? p.marketCap;
      p.volume24h = kas.usd_24h_vol ?? p.volume24h;
      p.live = p.live || {};
      p.live.priceChange24h = kas.usd_24h_change ?? null;
      p.live.lastUpdatedAt = kas.last_updated_at ?? null;
      p.live.source = "CoinGecko";
    }

    renderAll();

    if(status){
      const time = kas.last_updated_at ? new Date(kas.last_updated_at * 1000).toLocaleTimeString() : "";
      status.textContent = lang === "de"
        ? "KAS Live-Daten aktualisiert " + time
        : "KAS live data updated " + time;
    }
  }catch(e){
    console.error(e);
    if(status) status.textContent = lang === "de"
      ? "KAS Live-Daten nicht verfügbar – Demo-Daten aktiv"
      : "KAS live data unavailable – demo data active";
  }
}

/* Public live button loads KAS directly */
async function fetchAllLiveData(){
  await fetchKasLiveData();
}

/* Auto-load KAS after normal app initialization */
window.addEventListener("load", () => {
  setTimeout(fetchKasLiveData, 800);
  setInterval(fetchKasLiveData, 60000);
});


/* v3.1 Multi Asset Live Data
   CoinGecko IDs:
   KAS   -> kaspa
   KSKD  -> kaskad
   IGRA  -> igra
   iKAS  -> derived 1:1 from KAS
*/
const KEI_LIVE_IDS = {
  KAS: "kaspa",
  KSKD: "kaskad",
  IGRA: "igra"
};

function updateProjectFromCoinGecko(symbol, cgData){
  const p = projects.find(x => (x.symbol || "").toUpperCase() === symbol);
  if(!p || !cgData) return false;

  if(typeof cgData.usd === "number") p.price = cgData.usd;
  if(typeof cgData.usd_market_cap === "number") p.marketCap = cgData.usd_market_cap;
  if(typeof cgData.usd_24h_vol === "number") p.volume24h = cgData.usd_24h_vol;

  p.live = p.live || {};
  p.live.priceChange24h = typeof cgData.usd_24h_change === "number" ? cgData.usd_24h_change : null;
  p.live.lastUpdatedAt = cgData.last_updated_at || null;
  p.live.source = "CoinGecko";
  p.live.status = typeof cgData.usd === "number" ? "live" : "no-price";
  return typeof cgData.usd === "number";
}

function deriveIKasFromKas(){
  const kas = projects.find(x => (x.symbol || "").toUpperCase() === "KAS");
  const ikas = projects.find(x => (x.symbol || "").toUpperCase() === "IKAS");
  if(!kas || !ikas || !kas.price) return false;

  ikas.price = kas.price;
  ikas.marketCap = 0;
  ikas.volume24h = 0;
  ikas.live = ikas.live || {};
  ikas.live.priceChange24h = kas.live?.priceChange24h ?? null;
  ikas.live.lastUpdatedAt = kas.live?.lastUpdatedAt ?? null;
  ikas.live.source = "Derived from KAS 1:1";
  ikas.live.status = "derived";
  return true;
}

async function fetchEcosystemLiveData(){
  const status = document.getElementById("apiStatus");
  if(status) status.textContent = lang === "de" ? "Lade KEI Live-Daten..." : "Loading KEI live data...";

  try{
    const ids = Object.values(KEI_LIVE_IDS).join(",");
    const url = "https://api.coingecko.com/api/v3/simple/price?ids=" + encodeURIComponent(ids) + "&vs_currencies=usd&include_market_cap=true&include_24hr_vol=true&include_24hr_change=true&include_last_updated_at=true";
    const res = await fetch(url, { headers: { "accept": "application/json" } });
    if(!res.ok) throw new Error("CoinGecko API error " + res.status);

    const data = await res.json();

    let updated = 0;
    if(updateProjectFromCoinGecko("KAS", data.kaspa)) updated++;
    if(updateProjectFromCoinGecko("KSKD", data.kaskad)) updated++;
    if(updateProjectFromCoinGecko("IGRA", data.igra)) updated++;
    if(deriveIKasFromKas()) updated++;

    renderAll();

    if(status){
      status.textContent = lang === "de"
        ? "Live-Daten aktualisiert: " + updated + " Assets"
        : "Live data updated: " + updated + " assets";
    }
  }catch(e){
    console.error(e);
    if(status) status.textContent = lang === "de"
      ? "Live-Daten nicht verfügbar – Demo-/abgeleitete Daten aktiv"
      : "Live data unavailable – demo/derived data active";
  }
}

/* Override public live buttons */
async function fetchAllLiveData(){
  await fetchEcosystemLiveData();
}
async function fetchKasLiveData(){
  await fetchEcosystemLiveData();
}

/* Auto-refresh multi-asset live data */
window.addEventListener("load", () => {
  setTimeout(fetchEcosystemLiveData, 900);
  setInterval(fetchEcosystemLiveData, 60000);
});


/* v3.2 Dynamic KEI Score Engine
   KEI Score now adapts from:
   - Development base score
   - Adoption base score
   - Liquidity score from market cap + volume
   - Community base score
   - Fundamentals base score
   - Momentum from 24h price change
   - Risk penalty
*/
function clampScore(v){
  return Math.max(0, Math.min(100, Math.round(Number(v || 0))));
}

function liquidityLiveScore(p){
  const mc = Number(p.marketCap || 0);
  const vol = Number(p.volume24h || 0);

  let mcScore = 0;
  if(mc >= 1000000000) mcScore = 95;
  else if(mc >= 100000000) mcScore = 82;
  else if(mc >= 25000000) mcScore = 68;
  else if(mc >= 5000000) mcScore = 52;
  else if(mc >= 1000000) mcScore = 35;
  else if(mc > 0) mcScore = 20;

  let volScore = 0;
  if(vol >= 50000000) volScore = 95;
  else if(vol >= 5000000) volScore = 80;
  else if(vol >= 500000) volScore = 62;
  else if(vol >= 100000) volScore = 45;
  else if(vol > 0) volScore = 25;

  if(!mc && !vol) return Number(p.liquidity || 0);
  return clampScore((mcScore * 0.55) + (volScore * 0.45));
}

function momentumLiveScore(p){
  const ch = p.live && typeof p.live.priceChange24h === "number" ? p.live.priceChange24h : null;
  if(ch === null) return Number(p.momentumRaw || 0);

  if(ch >= 20) return 95;
  if(ch >= 10) return 88;
  if(ch >= 5) return 78;
  if(ch >= 2) return 68;
  if(ch >= 0) return 58;
  if(ch >= -3) return 48;
  if(ch >= -8) return 35;
  return 22;
}

function dynamicRiskScore(p){
  let risk = Number(p.riskRaw || 60);

  const mc = Number(p.marketCap || 0);
  const vol = Number(p.volume24h || 0);
  const source = p.live?.source || "";

  if(mc >= 1000000000) risk -= 18;
  else if(mc >= 100000000) risk -= 10;
  else if(mc >= 10000000) risk -= 4;
  else if(mc > 0 && mc < 3000000) risk += 8;

  if(vol >= 10000000) risk -= 8;
  else if(vol >= 500000) risk -= 4;
  else if(vol > 0 && vol < 100000) risk += 6;

  if(source === "CoinGecko") risk -= 4;
  if(source && source.includes("Derived")) risk += 8;
  if(!source) risk += 5;

  return clampScore(risk);
}

function dynamicKeiScore(p){
  const development = Number(p.development || 0);
  const adoption = Number(p.adoption || 0);
  const liquidity = liquidityLiveScore(p);
  const community = Number(p.community || 0);
  const fundamentals = Number(p.fundamentals || 0);
  const momentum = momentumLiveScore(p);
  const risk = dynamicRiskScore(p);

  const base =
    development * 0.24 +
    adoption * 0.20 +
    liquidity * 0.22 +
    community * 0.12 +
    fundamentals * 0.12 +
    momentum * 0.10;

  const penalty = risk > 70 ? 8 : risk > 55 ? 4 : risk < 30 ? -3 : 0;
  return clampScore(base - penalty);
}

/* Override original static KEI functions */
function keiScore(p){
  return dynamicKeiScore(p);
}

function opportunityScore(p){
  const kei = dynamicKeiScore(p);
  const momentum = momentumLiveScore(p);
  const safety = 100 - dynamicRiskScore(p);
  return clampScore((kei * 0.45) + (momentum * 0.35) + (safety * 0.20));
}

/* Improve project details with dynamic score breakdown */
function scoreBreakdownHtml(p){
  const liquidity = liquidityLiveScore(p);
  const momentum = momentumLiveScore(p);
  const risk = dynamicRiskScore(p);
  return `
    <div class="metrics">
      <div class="metric"><strong>${liquidity}/100</strong><span>Live Liquidity</span></div>
      <div class="metric"><strong>${momentum}/100</strong><span>Live Momentum</span></div>
      <div class="metric"><strong>${risk}/100</strong><span>Dynamic Risk</span></div>
      <div class="metric"><strong>${p.live?.source || "Manual"}</strong><span>Data Source</span></div>
    </div>
  `;
}

